// One item per active workflow, so Get last run can ask for the latest execution of each.
// Written without arrow functions, template literals or optional chaining on purpose: the n8n
// template portal rejects uploads that contain them.
var list = $input.first().json.data || [];
var out = [];
for (var i = 0; i < list.length; i++) {
  var w = list[i];
  if (!w.active || w.isArchived) continue;
  out.push({ json: { id: String(w.id), name: w.name, updatedAt: w.updatedAt || null, nodes: w.nodes || [], settings: w.settings || {} } });
}
// A check that cannot read must not report that all is well.
if (out.length === 0) {
  throw new Error('The n8n API returned no active workflows. Check baseUrl in Configuration and that the API key can see this instance.');
}
return out;

// Judges every workflow that starts itself against its own schedule, with the rule Duskwatch uses:
// silent once twice its interval plus five minutes has passed without a run. Workflows started from
// outside (webhooks, forms, chats, app triggers) are not judged. Idle is normal for them, and a check
// that calls idle broken gets muted within a week.
// Written without arrow functions, template literals or optional chaining on purpose: the n8n
// template portal rejects uploads that contain them.

var MINUTE = 60000;
// n8n deletes executions after 14 days unless configured otherwise. Past that, a missing run proves nothing.
var KEPT_MINUTES = 14 * 24 * 60;
var PER_UNIT = { seconds: 1 / 60, minutes: 1, hours: 60, days: 1440, weeks: 10080, months: 43200 };
// n8n leaves default values out of a saved workflow, so a missing value means the default.
var UNIT_DEFAULT = { seconds: 30, minutes: 5, hours: 1, days: 1, weeks: 1, months: 1 };

function positive(v) {
  return typeof v === 'number' && isFinite(v) && v > 0 ? v : null;
}

function toMinutes(value, unit) {
  return Math.max(1, Math.round(value * PER_UNIT[unit]));
}

function smaller(a, b) {
  if (a === null) return b;
  if (b === null) return a;
  return Math.min(a, b);
}

function isWholeNumber(s) {
  return s !== '' && String(parseInt(s, 10)) === s;
}

// Every-N notation in a cron field: an asterisk, a slash, a number. Gives the number, or null.
function everyN(s) {
  if (s.charAt(0) !== '*' || s.charAt(1) !== '/') return null;
  var n = s.slice(2);
  return isWholeNumber(n) ? Math.max(1, parseInt(n, 10)) : null;
}

var WEEKDAY_NAMES = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];

function rawWeekday(token) {
  var named = WEEKDAY_NAMES.indexOf(String(token).toLowerCase());
  if (named >= 0) return named;
  return isWholeNumber(token) && parseInt(token, 10) <= 7 ? parseInt(token, 10) : null;
}

// Longest gap in days between two allowed weekdays: Monday to Friday gives 3 (Friday to Monday).
function longestWeekdayGap(field) {
  var days = [];
  var items = field.split(',');
  for (var i = 0; i < items.length; i++) {
    var ends = items[i].split('-');
    var a = rawWeekday(ends[0]);
    var b = ends.length === 2 ? rawWeekday(ends[1]) : a;
    if (ends.length > 2 || a === null || b === null || b < a) return null;
    for (var d = a; d <= b; d++) if (days.indexOf(d % 7) < 0) days.push(d % 7);
  }
  days.sort(function (x, y) { return x - y; });
  var longest = 0;
  for (var j = 0; j < days.length; j++) {
    var next = j + 1 < days.length ? days[j + 1] : days[0] + 7;
    longest = Math.max(longest, next - days[j]);
  }
  return longest;
}

// Fixed rhythms only: every N minutes or hours, a fixed minute every hour, a fixed time every day or
// on set weekdays (then the longest gap between two of them counts). Days of the month and the like
// give null, and the workflow is listed as not covered.
function cronMinutes(expression) {
  var parts = String(expression || '').split(' ').filter(function (p) { return p !== ''; });
  if (parts.length === 6) parts = parts.slice(1);
  if (parts.length !== 5) return null;
  var minute = parts[0];
  var hour = parts[1];
  var everyDay = parts[4] === '*' || parts[4] === '?';
  if (parts[2] !== '*' || parts[3] !== '*') return null;
  if (everyN(minute) !== null && hour === '*') return everyDay ? everyN(minute) : null;
  if (!isWholeNumber(minute)) return null;
  if (hour === '*') return everyDay ? 60 : null;
  if (everyN(hour) !== null) return everyDay ? everyN(hour) * 60 : null;
  if (!isWholeNumber(hour)) return null;
  if (everyDay) return 1440;
  var gap = longestWeekdayGap(parts[4]);
  return gap === null ? null : gap * 1440;
}

function scheduleRuleMinutes(rule) {
  var field = rule.field || 'days';
  if (field === 'cronExpression') return cronMinutes(rule.expression);
  if (!PER_UNIT.hasOwnProperty(field)) return null;
  return toMinutes(positive(rule[field + 'Interval']) || UNIT_DEFAULT[field], field);
}

function legacyCronMinutes(item) {
  var mode = item.mode || 'everyDay';
  if (mode === 'everyMinute') return 1;
  if (mode === 'everyHour') return 60;
  if (mode === 'everyDay') return 1440;
  if (mode === 'everyWeek') return 10080;
  if (mode === 'everyMonth') return 43200;
  if (mode === 'everyX') return toMinutes(positive(item.value) || 1, item.unit === 'hours' ? 'hours' : 'minutes');
  if (mode === 'custom') return cronMinutes(item.cronExpression);
  return null;
}

// Does the workflow start itself, and if so, how often? Disabled trigger nodes do not count.
function scheduleOf(nodes) {
  var scheduled = false;
  var minutes = null;
  for (var i = 0; i < nodes.length; i++) {
    var node = nodes[i];
    var p = node.parameters || {};
    if (node.disabled) continue;
    if (node.type === 'n8n-nodes-base.scheduleTrigger') {
      scheduled = true;
      var rules = p.rule ? p.rule.interval || [] : [{}];
      for (var r = 0; r < rules.length; r++) minutes = smaller(minutes, scheduleRuleMinutes(rules[r]));
    } else if (node.type === 'n8n-nodes-base.cron') {
      scheduled = true;
      var items = (p.triggerTimes && p.triggerTimes.item) || [];
      for (var c = 0; c < items.length; c++) minutes = smaller(minutes, legacyCronMinutes(items[c]));
    } else if (node.type === 'n8n-nodes-base.intervalTrigger') {
      scheduled = true;
      minutes = smaller(minutes, toMinutes(positive(p.interval) || 1, PER_UNIT.hasOwnProperty(p.unit) ? p.unit : 'seconds'));
    }
  }
  return { scheduled: scheduled, minutes: minutes };
}

function every(minutes) {
  if (minutes % 1440 === 0) return minutes === 1440 ? 'every day' : 'every ' + minutes / 1440 + ' days';
  if (minutes % 60 === 0) return minutes === 60 ? 'every hour' : 'every ' + minutes / 60 + ' hours';
  return minutes === 1 ? 'every minute' : 'every ' + minutes + ' minutes';
}

var now = Date.now();
var workflows = $('One item per workflow').all();
var lookups = $input.all();
var findings = [];
var notCovered = [];
var judged = 0;
var notScheduled = 0;

function notJudged(w, reason) {
  notCovered.push({ workflow: w.name, workflowId: w.id, reason: reason });
}

for (var i = 0; i < workflows.length; i++) {
  var w = workflows[i].json;
  var schedule = scheduleOf(w.nodes || []);
  if (!schedule.scheduled) {
    notScheduled++;
    continue;
  }
  if (schedule.minutes === null) {
    notJudged(w, 'Its schedule has no fixed rhythm, certain days of the month for example, so there is no gap to measure against.');
    continue;
  }
  if (w.settings && w.settings.saveDataSuccessExecution === 'none') {
    notJudged(w, 'It is set not to save successful executions, so a healthy run leaves no trace to find.');
    continue;
  }
  var allowed = Math.max(2 * schedule.minutes + 5, 10);
  var runs = (lookups[i] && lookups[i].json && lookups[i].json.data) || [];
  var last = runs.length > 0 ? Date.parse(runs[0].startedAt || runs[0].createdAt) : NaN;
  if (isNaN(last)) {
    if (allowed > KEPT_MINUTES) {
      notJudged(w, 'No saved execution, but it runs less often than n8n keeps executions by default, so that proves nothing.');
      continue;
    }
    var changed = Date.parse(w.updatedAt);
    if (!isNaN(changed) && now - changed < allowed * MINUTE) {
      notJudged(w, 'Changed recently and has not run since. Too early to tell.');
      continue;
    }
    judged++;
    findings.push({ workflow: w.name, workflowId: w.id, expected: every(schedule.minutes), lastRun: null, hoursSilent: null, note: 'no execution in the saved history' });
    continue;
  }
  judged++;
  if (now - last > allowed * MINUTE) {
    findings.push({ workflow: w.name, workflowId: w.id, expected: every(schedule.minutes), lastRun: new Date(last).toISOString(), hoursSilent: Math.round((now - last) / (60 * MINUTE)), note: 'missed at least two scheduled runs' });
  }
}

// Half or more of the judged workflows silent: suspect the check before believing it. This counts
// workflows, not alerts, and it stays a suspicion. A restart that did not re-register the schedule
// triggers really does stop everything at once.
var checkSuspect = judged >= 4 && findings.length * 2 >= judged;
var hint = checkSuspect
  ? 'Half or more of the scheduled workflows look silent. Either they really all stopped, which is what a restart that did not re-register the schedule triggers looks like, or this check cannot see what it needs, most often because the instance does not save successful executions (EXECUTIONS_DATA_SAVE_ON_SUCCESS=none). Open one of them in n8n and look at its executions before acting on this.'
  : '';

var lines = [];
for (var f = 0; f < findings.length; f++) {
  var x = findings[f];
  lines.push(x.workflow + ' (' + (x.lastRun ? 'last run ' + x.hoursSilent + ' h ago' : 'no saved run') + ', expected ' + x.expected + ')');
}
var summary = judged === 0
  ? 'No scheduled workflow could be judged.'
  : findings.length === 0
    ? 'No scheduled workflow missed its schedule (' + judged + ' checked).'
    : findings.length + ' of ' + judged + ' checked workflows missed their schedule: ' + lines.join('; ') + '.';
if (notCovered.length > 0) summary += ' ' + notCovered.length + ' could not be judged, see notCovered.';
if (hint) summary += ' ' + hint;

return [{ json: { silent: findings.length, summary: summary, findings: findings, notCovered: notCovered, judged: judged, notScheduled: notScheduled, checkSuspect: checkSuspect, hint: hint } }];
